def withErrorMessage(message: String): Unit = {
  try {
    withError("Something went wrong")
  } catch (error) {
    println(error) // Output: Something went wrong
  } finally {
    println("Futures finished")
  }
}

def withFailureMessage(message: String): Unit = {
  try {
    withFailure("Something went wrong")
  } catch (error) {
    println(error) // Output: Something went wrong
  } else if (error == "something went wrong") {
    println("Futures finished")
  } else {
    println("Failed to handle exception")
  }
}
```

Note: The `withErrorMessage` method returns a new object, while the `withFailureMessage` method returns a new object. If you want both objects, use `withErrorMessage`. If you only want one object, use `withFailureMessage`.

